"""Validation for requests generated by the travel model."""

from datetime import date
from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, StringConstraints, model_validator


Place = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=100, pattern=r"^[^\x00-\x1f\x7f]+$")]
DateText = Annotated[str, StringConstraints(pattern=r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")]
PartySize = Annotated[int, Field(ge=1, le=9)]


class InvalidToolArguments(ValueError):
    """A model tool request failed validation."""


class SearchArguments(BaseModel):
    model_config = ConfigDict(strict=True, extra="forbid")

    destination: Place


class FlightArguments(SearchArguments):
    origin: Place
    departure_date: DateText
    return_date: DateText | None = None
    trip_type: Literal["round_trip", "one_way"] | None = None
    adults: PartySize
    currency: Literal["INR"] = "INR"

    @model_validator(mode="after")
    def check_trip(self):
        departure = date.fromisoformat(self.departure_date)
        if departure < date.today() or self.origin.casefold() == self.destination.casefold():
            raise ValueError("Departure must be today or later and airports must differ.")
        if self.return_date is None:
            if self.trip_type == "round_trip":
                raise ValueError("A round trip needs a return date.")
        elif self.trip_type == "one_way" or date.fromisoformat(self.return_date) < departure:
            raise ValueError("A return date requires a round trip and cannot precede departure.")
        return self


class HotelArguments(SearchArguments):
    check_in_date: DateText
    check_out_date: DateText
    adults: PartySize
    rooms: PartySize = 1
    currency: Literal["INR"] = "INR"

    @model_validator(mode="after")
    def check_stay(self):
        check_in = date.fromisoformat(self.check_in_date)
        if check_in < date.today() or date.fromisoformat(self.check_out_date) <= check_in:
            raise ValueError("Check-in must be today or later and checkout must follow check-in.")
        return self


class RestaurantArguments(SearchArguments):
    radius_meters: Annotated[int, Field(ge=500, le=50000)] = 5000
    limit: Annotated[int, Field(ge=1, le=20)] = 10


class AttractionArguments(SearchArguments):
    radius_meters: Annotated[int, Field(ge=1000, le=50000)] = 12000
    limit: Annotated[int, Field(ge=1, le=20)] = 12


TOOL_ARGUMENTS = {
    "search_flights": FlightArguments,
    "search_hotels": HotelArguments,
    "search_restaurants": RestaurantArguments,
    "search_attractions": AttractionArguments,
}
